//! 🧪️ The real NativeWindow App follows original ledger rows through installed semantics and one shared visibility event.
use super::*;
use fixture::{NativeWindowApp as App,State,Mutation,Owner};
use semio_framework_plugin_window_config::{WindowConfigOwner,WindowConfigOwnerRegistry,WindowConfigMutation};
use semio_framework_plugin_tool_run::tool_jobs_tool_machine::{ToolMachineRuntime,OriginalToolMachineFollow,PressLeaf};
use semio_framework_tool_machine::{ScrubInput,TypingInput,TypingFold};
const POLICY:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096};
fn funded<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,grant:RetainedCloneGrant,f:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(grant,decoder,f));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"native follower original receipt {p:?} failure={:?}",result.as_ref().err());result.unwrap()}
fn exact(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=POLICY.maximum_copy_bytes&&d.capacity_bytes<=POLICY.maximum_capacity_bytes,"native mounted source exceeds actual policy: {d:?}");RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn denied(d:RetirementDemand,mut f:impl FnMut(RetainedCloneGrant)){let exact=exact(d);for axis in 0..5{let mut g=exact;match axis{0=>g.maximum_items=0,1 if d.copy_bytes>0=>g.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>g.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>g.maximum_release_bytes-=1,4 if d.depth>0=>g.maximum_depth-=1,_=>continue}f(g)}}
#[test]
fn native_original_follower_keeps_all_lanes_private_then_publishes_complete_prefix(){
 let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let actor=store::ActorId("native-follow".into());let mut owner=None;funded(&mut caller,&mut decoder,POLICY,|cx|OriginalArtifactStoreSet::<App>::admit("native-follow",&actor,cx,&mut owner));let birth=owner.as_mut().unwrap();let mut stores=None;for index in 0..1048576{if funded(&mut caller,&mut decoder,POLICY,|cx|birth.step(cx)){break}assert!(index<1048575)}funded(&mut caller,&mut decoder,POLICY,|cx|birth.take(&mut stores,cx));while !birth.terminal_is_empty(){funded(&mut caller,&mut decoder,POLICY,|cx|cx.with_original_retirement(|cx|birth.close_step(cx)));}release_owner(&mut owner,&mut caller,&mut decoder);let mut stores=stores.unwrap();
 let mut windows=WindowConfigOwnerRegistry::new(store::ActorId("follow-window-actor".into()));windows.register::<Owner>().unwrap();for window in ["left","right"]{let view=semio_framework::ViewModel{window_id:Some(window.into()),window_instances:vec![semio_framework::WindowInstance{id:window.into(),window_kind_id:Owner::WINDOW_KIND_ID.into(),..Default::default()}],..Default::default()};for index in 0..262144{if funded(&mut caller,&mut decoder,POLICY,|cx|windows.ensure_for_view(Some(&view),cx)){break}assert!(index<262143)}}
 let mut machines=ToolMachineRuntime::<State,Mutation,State,Mutation>::default();let leaves=vec![PressLeaf::Member(Mutation::Zoom{zoom:2.5}),PressLeaf::Config(Mutation::Zoom{zoom:3.5}),PressLeaf::WindowConfig(WindowConfigMutation::of::<Owner>("left",Mutation::Zoom{zoom:5.0})),PressLeaf::WindowConfig(WindowConfigMutation::of::<Owner>("right",Mutation::Zoom{zoom:7.0}))];let mut input=Some(ScrubInput::Tick{gesture:"follow-press".into(),leaves});machines.presses.send("left","native#press",&actor,"base",&mut input,semio_framework_tool_machine::authoring_clock(0)).unwrap();machines.typing.send("right","native#typing",&actor,TypingInput::Edit{buffer:"zoom".into(),leaves:vec![Mutation::Zoom{zoom:8.0}]},|_,next|TypingFold::Net(next.to_vec()),semio_framework_tool_machine::authoring_clock(1)).unwrap();let press_pointer=machines.presses.open("left").unwrap().entries.as_ptr();let typing_pointer=machines.typing.open("right").unwrap().entries.as_ptr();machines.refold_owed=true;machines.refold_request=1;let mut follow=None;let d=OriginalToolMachineFollow::<App>::admission_demands();denied(d,|g|{assert!(!funded(&mut caller,&mut decoder,g,|cx|OriginalToolMachineFollow::<App>::admit(&machines,&stores.document,&stores.config,cx,&mut follow)));assert!(follow.is_none());assert_eq!(caller.receipt(),Default::default())});assert!(funded(&mut caller,&mut decoder,exact(d),|cx|OriginalToolMachineFollow::<App>::admit(&machines,&stores.document,&stores.config,cx,&mut follow)));let follow=follow.as_mut().unwrap();let mut published=false;let mut idle=0;
 for index in 0..262144{if follow.terminal_is_empty(){break}let before=follow.progress();let d=follow.demands(&stores.document,&stores.config,&windows,&machines).unwrap();denied(d,|g|{assert!(!funded(&mut caller,&mut decoder,g,|cx|follow.advance(&stores.document,&stores.config,&mut windows,&mut machines,cx)));assert_eq!(caller.receipt(),Default::default(),"denied original source changed its receipt at {before:?}");assert_eq!(follow.progress(),before)});funded(&mut caller,&mut decoder,exact(d),|cx|follow.advance(&stores.document,&stores.config,&mut windows,&mut machines,cx));published|=follow.progress().4;let actual=[machines.overlay.as_ref().map_or(1.25,|state|state.zoom),machines.config_overlay.as_ref().map_or(1.25,|state|state.zoom),windows.borrow_preview(Owner::WINDOW_KIND_ID,"left").unwrap().get::<Owner>().unwrap().zoom,windows.borrow_preview(Owner::WINDOW_KIND_ID,"right").unwrap().get::<Owner>().unwrap().zoom];assert_eq!(actual,if published{[8.0,3.5,5.0,7.0]}else{[1.25;4]});if caller.receipt()==Default::default(){idle+=1}else{idle=0}assert!(idle<16,"original follower stalled at {:?} d={d:?}",follow.progress());assert!(index<262143,"original follower horizon {:?}",follow.progress());}
 assert!(published);assert!(!machines.refold_owed);assert_eq!(machines.presses.open("left").unwrap().entries.as_ptr(),press_pointer);assert_eq!(machines.typing.open("right").unwrap().entries.as_ptr(),typing_pointer);let d=follow.shell_close_demands();let _=follow;funded(&mut caller,&mut decoder,exact(d),|cx|{close_original_retained_step(cx,d,|_|{drop(follow.take());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())});
 let mut document_close=semio_framework_plugin_tool_run::original_operations::OriginalToolOverlayFold::<State,Mutation>::default();let mut config_close=semio_framework_plugin_tool_run::original_operations::OriginalToolOverlayFold::<State,Mutation>::default();for _ in 0..65536{if document_close.terminal_is_empty()&&machines.overlay.is_none(){break}funded(&mut caller,&mut decoder,POLICY,|cx|cx.with_original_retirement(|cx|{if machines.overlay.is_some(){document_close.close_external_alias(&stores.document,&mut machines.overlay,cx)}else{document_close.close_step(&stores.document,cx)}}));}for _ in 0..65536{if config_close.terminal_is_empty()&&machines.config_overlay.is_none(){break}funded(&mut caller,&mut decoder,POLICY,|cx|cx.with_original_retirement(|cx|{if machines.config_overlay.is_some(){config_close.close_external_alias(&stores.config,&mut machines.config_overlay,cx)}else{config_close.close_step(&stores.config,cx)}}));}
 for index in 0..1048576{if windows.terminal_is_empty(){break}let d=windows.retirement_demands(4096).unwrap();funded(&mut caller,&mut decoder,exact(d),|cx|cx.with_original_retirement(|cx|windows.close_step_context(cx.retained_grant(),cx).map(|_|()).map_err(Into::into)));assert!(index<1048575)}for lane in 0..4{for index in 0..1048576{let terminal=match lane{0=>stores.document.close_owned_store_terminal_is_empty(),1=>stores.config.close_owned_store_terminal_is_empty(),2=>stores.draft.close_owned_store_terminal_is_empty(),_=>stores.interaction.close_owned_store_terminal_is_empty()};if terminal{break}funded(&mut caller,&mut decoder,POLICY,|cx|cx.with_original_retirement(|cx|{let d=match lane{0=>stores.document.close_owned_demands(4096)?,1=>stores.config.close_owned_demands(4096)?,2=>stores.draft.close_owned_demands(4096)?,_=>stores.interaction.close_owned_demands(4096)?};close_original_retained_step(cx,d,|g|match lane{0=>stores.document.close_owned_store_step(g),1=>stores.config.close_owned_store_step(g),2=>stores.draft.close_owned_store_step(g),_=>stores.interaction.close_owned_store_step(g)})?;Ok(())}));assert!(index<1048575)}}while !funded(&mut caller,&mut decoder,POLICY,|cx|stores.close_step(cx)){}retire_decoder(&mut caller,&mut decoder);caller.retire(POLICY);
}
